mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM cases
    WHERE id = #{caseId}
      AND user_id = #{userId}
)

SELECT g.id
FROM cases c
JOIN users u ON u.id = c.user_id
JOIN gmail_connections g ON g.user_id = u.id
WHERE c.id = #{caseId}
  AND u.id = #{userId}
  AND u.users_status = 'ACTIVE'
  AND u.deleted_at IS NULL
  AND g.id = #{connectionId}
  AND g.google_email = #{googleEmail}
  AND g.gmail_connections_status = 'CONNECTED'
FOR UPDATE OF u, c, g

